	/// <summary>
	/// Handles adding the list of parameters to a new command.
	/// </summary>
	/// <param name="command">The command to add parameters to.</param>
	protected abstract void AddParams(TCommand command);
	#endregion

	/// <summary>
	/// Sets the timeout value.
	/// </summary>
	/// <param name="seconds">The number of seconds to wait before the connection times out.</param>
	/// <returns>This instance for use in method chaining.</returns>
	public TThis SetTimeout(ushort seconds)
	{
		Timeout = seconds;
		return (TThis)this;
	}

	#region Derived parameter names

	/// <summary>
	/// Gets the names of the parameters a stored procedure declares, so a parameter added with <c>AddParam(value)</c> can be matched to the real one.
	/// A provider that can look this up overrides it (<see cref="ExpressiveDbCommand"/> and <see cref="ExpressiveCommand"/> ask the ADO.NET schema collection <c>ProcedureParameters</c> of a <see cref="DbConnection"/>); the default returns nothing, and the last member of each argument is used as written.
	/// </summary>
	/// <remarks>
	/// Return the names exactly as the provider spells them: a leading <c>@</c> is ignored when matching, nothing else is changed, and the name that is sent is the one returned.
	/// An empty or default array means "not known", which also covers a procedure that declares no parameters; it is never remembered.
	/// </remarks>
	/// <param name="connection">An open connection to run the lookup on. A command that executes inside a transaction must use <see cref="Transaction"/>.</param>
	/// <param name="procedure">The procedure name as given to the command.</param>
	/// <returns>The names as the provider reports them (a leading <c>@</c> is fine), or an empty or default array when they are not known.</returns>
	protected virtual ImmutableArray<string> GetProcedureParameterNames(TConnection connection, string procedure)
		=> default;

	/// <summary>The asynchronous twin of <see cref="GetProcedureParameterNames"/>.</summary>
	/// <param name="connection">An open connection to run the lookup on.</param>
	/// <param name="procedure">The procedure name as given to the command.</param>
	/// <param name="cancellationToken">The cancellation token of the call: the command's cancellation token, together with the one passed to the terminal (for example <c>ToListAsync(token)</c>) when there is one.</param>
	/// <returns>The names as the provider reports them, or an empty or default array when they are not known.</returns>
	protected virtual ValueTask<ImmutableArray<string>> GetProcedureParameterNamesAsync(TConnection connection, string procedure, CancellationToken cancellationToken)
		=> new(GetProcedureParameterNames(connection, procedure));

	// The names of a text command, by the command text itself (by reference): a literal or a kept string stays remembered, and the entry goes when the string is released.
	// A text with no @name marker has a set with no names, which means "not known".
	static readonly ConditionalWeakTable<string, NameSet> TextNames = new();

	// Runs after the connection is open and before the command is built, once per command: it replaces the provisional names with the real ones.
	// What is remembered is a NameSet (the names and the match found for each argument), so a repeat execution allocates nothing to resolve.
	void ResolveDerivedParams(TConnection connection)
	{
		if (!_hasDerivedParams) return;

		NameSet? names = null;
		bool remembered = false;
		if (Type == CommandType.StoredProcedure)
		{
			ProcedureKey key = ProcedureKey(connection);
			remembered = ProcedureNameCache.TryGet(NameCacheOwner, key, out names);
			if (!remembered) names = Remember(key, GetProcedureParameterNames(connection, Command));
		}
		else if (Type == CommandType.Text)
		{
			names = TextNames.GetValue(Command, static text => new NameSet(SqlTextParameters.Parse(text))); // the @name markers found in the text
		}

		if (ApplyDerivedNames(names, final: !remembered)) return;

		// The remembered names did not fit: the procedure may have changed since they were read. Read them again before deciding that nothing matches.
		names = Remember(ProcedureKey(connection), GetProcedureParameterNames(connection, Command));
		ApplyDerivedNames(names, final: true);
	}

	// Not an async method itself: when the names are remembered (the usual case) it finishes without a state machine or an await; only reading them is asynchronous.
	ValueTask ResolveDerivedParamsAsync(TConnection connection, CancellationToken cancellationToken)
	{
		NameSet? names = null;
		bool remembered = false;
		if (Type == CommandType.StoredProcedure)
		{
			remembered = ProcedureNameCache.TryGet(NameCacheOwner, ProcedureKey(connection), out names);
			if (!remembered) return ReadNamesAndApplyAsync(connection, cancellationToken);
		}
		else if (Type == CommandType.Text)
		{
			names = TextNames.GetValue(Command, static text => new NameSet(SqlTextParameters.Parse(text))); // the @name markers found in the text
		}

		if (ApplyDerivedNames(names, final: !remembered)) return default;

		// The remembered names did not fit: the procedure may have changed since they were read. Read them again before deciding that nothing matches.
		return ReadNamesAndApplyAsync(connection, cancellationToken);
	}

	async ValueTask ReadNamesAndApplyAsync(TConnection connection, CancellationToken cancellationToken)
	{
		NameSet? names = Remember(ProcedureKey(connection), await GetProcedureParameterNamesAsync(connection, Command, cancellationToken).ConfigureAwait(false));
		ApplyDerivedNames(names, final: true);
	}

	// Remembers the names a procedure reported and returns the set made from them; an empty answer is "not known" (null) and is not remembered.
	NameSet? Remember(ProcedureKey key, ImmutableArray<string> names)
		=> names.IsDefaultOrEmpty ? null : ProcedureNameCache.Set(NameCacheOwner, key, names);

	// Remembered names belong to the object commands take connections from: a factory (not the wrapper made around it for each command), a pool, or the bare connection.
	object NameCacheOwner => _poolOrConnection switch
	{
		DbConnectionFactoryExtensions.ConnectionFactoryToPoolAdapter<TConnection> typed => typed.Identity,
		DbConnectionFactoryExtensions.ConnectionFactoryToPoolAdapter untyped => untyped.Identity,
		_ => _poolOrConnection,
	};

	// The server and the database are part of the key: one connection can be switched to another database, and one factory can hand out connections to different servers,
	// where the same procedure name may be a different procedure. IDbConnection has no server name, so a connection that is not a DbConnection contributes none.
	// The key is a struct of the three parts, so no string is built.
	ProcedureKey ProcedureKey(TConnection connection) => new((connection as DbConnection)?.DataSource, connection.Database, Command);

	// Returns false, leaving the parameters untouched, when an argument named by the caller matches none of the real names and `final` is false (the names may be out of date).
	// `real` is null when the names are not known (and has no names for a text without markers): each argument then keeps its last member as written.
	bool ApplyDerivedNames(NameSet? real, bool final)
	{
		List<Param> list = Params;
		int count = list.Count;

		// The name each parameter ends up with (null: not sent), in a pooled array; only the used part is cleared when it goes back.
		string?[] names = ArrayPool<string?>.Shared.Rent(count);
		try
		{
			return Apply(list, count, names, real, final);
		}
		finally
		{
			Array.Clear(names, 0, count);
			ArrayPool<string?>.Shared.Return(names);
		}
	}

	bool Apply(List<Param> list, int count, string?[] names, NameSet? real, bool final)
	{
		bool known = real is { Names.Length: > 0 };

		// Resolve each name. Without the real names the last member is used as written.
		for (int i = 0; i < count; i++)
		{
			Param p = list[i];
			if (p.Expression is not { } expression)
			{
				names[i] = p.Name;
				continue;
			}

			string? name = known ? real!.Match(expression, Command) : p.Name;
			if (name is null)
			{
				// A member of an object that the procedure does not take is simply not sent; an argument named by the caller must match.
				if (p.FromObject) continue; // names[i] stays null
				if (!final) return false;
				throw NoMatch(expression, real!.Names);
			}

			names[i] = name;
		}

		// A parameter named by the caller wins over a member of an object that resolves to the same name.
		// The ones compared against are never members of an object, so dropping a member does not change the answer for another.
		for (int i = 0; i < count; i++)
		{
			if (names[i] is not { } member || !list[i].FromObject) continue;
			for (int j = 0; j < count; j++)
			{
				if (j != i && names[j] is { } other && !list[j].FromObject && SameName(member, other))
				{
					names[i] = null;
					break;
				}
			}
		}

		// Two arguments that resolve to one parameter would silently overwrite each other.
		for (int i = 0; i < count; i++)
		{
			if (names[i] is not { } first) continue;
			for (int j = i + 1; j < count; j++)
			{
				if (names[j] is { } second && SameName(first, second))
					throw Collision(first, list[i], list[j], real?.Names ?? default);
			}
		}

		// Keep what is sent, in order, under its resolved name.
		int written = 0;
		for (int i = 0; i < count; i++)
		{
			if (names[i] is not { } name) continue;
			Param p = list[i];
			list[written++] = p.Expression is null ? p : p.Resolved(name);
		}

		list.RemoveRange(written, count - written);
		_hasDerivedParams = false;
		return true;
	}

	static bool SameName(string a, string b) => Bare(a).Equals(Bare(b), StringComparison.OrdinalIgnoreCase);

	static ReadOnlySpan<char> Bare(string name) => name.Length > 0 && name[0] == '@' ? name.AsSpan(1) : name.AsSpan();

	// What the caller wrote for a parameter, for the message of a collision.
	static string Written(Param original)
		=> original.Expression is { } expression
			? original.FromObject ? $"the member '{expression}' of the AddParams object" : $"the argument '{expression}'"
			: $"the name '{original.Name}' you passed";

	InvalidOperationException Collision(string name, Param first, Param second, ImmutableArray<string> real)
		=> new($"Two parameters resolve to '{name}': {Written(first)} and {Written(second)}. "
			+ (real.IsDefaultOrEmpty
				? "The parameter names are not known, so each argument is used under its last member as written."
				: $"The procedure '{Command}' declares: {string.Join(", ", real)}.")
			+ " Name one of them explicitly: AddParam(\"name\", value).");

	InvalidOperationException NoMatch(string expression, ImmutableArray<string> real)
		=> new($"The argument '{expression}' matches none of the parameters of '{Command}' (tried {string.Join(", ", ParameterNames.Candidates(expression))}). The procedure declares: {string.Join(", ", real)}. Name the parameter explicitly: AddParam(\"name\", value).");

	#endregion

	#region Execution core

	// Every execution path funnels through these two methods: take the connection, make sure it is open,
	// build the command, run the caller's function, release the connection. The caller's inputs travel in
	// TState (a value type for the typed paths) and the functions are static lambdas, so a call allocates
	// no closures or delegates of its own.

	// Open MUST occur before command creation as some DbCommands require it.
	private protected TResult ExecuteCore<TState, TResult>(TState state, Func<TCommand, ConnectionState, TState, TResult> func)
	{
		if (_poolOrConnection is TConnection single)
			return ExecuteDirect(single, state, func);

		var pool = (IDbConnectionPool<TConnection>)_poolOrConnection;
		TConnection conn = pool.Take();
		try
		{
			ConnectionState prior = conn.EnsureOpen();
			ResolveDerivedParams(conn);
			using TCommand cmd = PrepareCommand(conn);
			return func(cmd, prior, state);
		}
		finally
		{
			pool.Give(conn);
		}
	}

	// The terminals that take a token: it is used together with the command's own, and either cancels. The lambda is given the token that governs the call.
	[SuppressMessage("Design", "CA1068:CancellationToken parameters must come last")]
	private protected ValueTask<TResult> ExecuteCombinedAsync<TResult>(CancellationToken callToken, Func<TCommand, ConnectionState, CancellationToken, ValueTask<TResult>> func)
		=> CancellationTokens.RunAsync(CancellationToken, callToken, (self: this, func), static (s, token) => s.self.ExecuteCoreAsync(token, s.func, token));

	private protected ValueTask<TResult> ExecuteCoreAsync<TState, TResult>(TState state, Func<TCommand, ConnectionState, TState, ValueTask<TResult>> func)
		=> ExecuteCoreAsync(state, func, CancellationToken);

	// The token governs the whole call: the first check, the connection open, the name lookup, and (through the state, which the caller builds) the execute and the reads.
	private protected async ValueTask<TResult> ExecuteCoreAsync<TState, TResult>(TState state, Func<TCommand, ConnectionState, TState, ValueTask<TResult>> func, CancellationToken cancellationToken)
	{
		cancellationToken.ThrowIfCancellationRequested(); // Since cancelled awaited tasks throw, we will follow the same pattern here.

		if (_poolOrConnection is TConnection single)
		{
			EnterDirect();
			ConnectionState before = single.State;
			try
			{
				ConnectionState prior = await OpenIfNeededAsync(single, cancellationToken).ConfigureAwait(false);
				if (_hasDerivedParams) await ResolveDerivedParamsAsync(single, cancellationToken).ConfigureAwait(false);
				using TCommand cmd = PrepareCommand(single);
				return await func(cmd, prior, state).ConfigureAwait(false);
			}
			finally
			{
				ExitDirect(single, before);
			}
		}

		var pool = (IDbConnectionPool<TConnection>)_poolOrConnection;
		TConnection conn = pool.Take();
		try
		{
			ConnectionState prior = await OpenIfNeededAsync(conn, cancellationToken).ConfigureAwait(false);
			if (_hasDerivedParams) await ResolveDerivedParamsAsync(conn, cancellationToken).ConfigureAwait(false);
			using TCommand cmd = PrepareCommand(conn);
			return await func(cmd, prior, state).ConfigureAwait(false);
		}
		finally
		{
			pool.Give(conn);
		}
	}

	// An open connection (the usual case) needs no awaiting at all.
	static ValueTask<ConnectionState> OpenIfNeededAsync(TConnection connection, CancellationToken cancellationToken)
	{
		ConnectionState state = connection.State;
		return (state & (ConnectionState.Open | ConnectionState.Broken)) == ConnectionState.Open
			? new ValueTask<ConnectionState>(state)
			: connection.EnsureOpenAsync(cancellationToken);
	}

	TResult ExecuteDirect<TState, TResult>(TConnection single, TState state, Func<TCommand, ConnectionState, TState, TResult> func)
	{
		EnterDirect();
		ConnectionState before = single.State;
		try
		{
			ConnectionState prior = single.EnsureOpen();
			ResolveDerivedParams(single);
			using TCommand cmd = PrepareCommand(single);
			return func(cmd, prior, state);
		}
		finally
		{
			ExitDirect(single, before);
		}
	}

	// A connection that was closed when taken is closed again when released; one that was open stays open.
	void EnterDirect()
	{
		if (Interlocked.CompareExchange(ref _busy, 1, 0) != 0)
			throw new InvalidOperationException("Concurrent use of a single connection is not supported.");
	}

	void ExitDirect(TConnection connection, ConnectionState before)
	{
		try
		{
			if (before == ConnectionState.Closed) connection.Close();
		}
		finally
		{
			Volatile.Write(ref _busy, 0);
		}
	}

	#endregion

	/// <inheritdoc />
	public void Execute(Action<TCommand> action)
	{
		if (action is null) throw new ArgumentNullException(nameof(action));
		Contract.EndContractBlock();

		ExecuteCore(action, static (cmd, _, a) =>
		{
			a(cmd);
			return false;
		});
	}

	/// <inheritdoc />
	public T Execute<T>(Func<TCommand, T> transform)
	{
		if (transform is null) throw new ArgumentNullException(nameof(transform));
		Contract.EndContractBlock();

		return ExecuteCore(transform, static (cmd, _, f) => f(cmd));
	}

	/// <inheritdoc />
	public virtual ValueTask ExecuteAsync(Func<TCommand, ValueTask> handler)
	{
		if (handler is null) throw new ArgumentNullException(nameof(handler));
		Contract.EndContractBlock();

		CancellationToken.ThrowIfCancellationRequested(); // Thrown synchronously, as before.

		return ValueTaskHelpers.Discard(ExecuteCoreAsync(handler, static async (cmd, _, h) =>
		{
			await h(cmd).ConfigureAwait(false);
			return false;
		}));
	}

	// Completes a ValueTask<T> as a plain ValueTask without allocating when it has already finished.
	/// <inheritdoc />
	public virtual ValueTask<T> ExecuteAsync<T>(Func<TCommand, ValueTask<T>> transform)
	{
		if (transform is null) throw new ArgumentNullException(nameof(transform));
		Contract.EndContractBlock();

		CancellationToken.ThrowIfCancellationRequested(); // Thrown synchronously, as before.

		return ExecuteCoreAsync(transform, static (cmd, _, f) => f(cmd));
	}

	void IExecuteCommand.Execute(Action<IDbCommand> action)
		=> Execute(command => action(command));

	T IExecuteCommand.Execute<T>(Func<IDbCommand, T> transform)
		=> Execute(command => transform(command));

	ValueTask IExecuteCommand.ExecuteAsync(Func<IDbCommand, ValueTask> handler)
		=> ExecuteAsync(command => handler(command));

	ValueTask<T> IExecuteCommand.ExecuteAsync<T>(Func<IDbCommand, ValueTask<T>> transform)
		=> ExecuteAsync(command => transform(command));

	/// <summary>
	/// Validates and properly acquires the expected type of the reader.
	/// </summary>
	/// <typeparam name="TActual">The actual type of the reader.</typeparam>
	/// <param name="reader">The reader to cast.</param>
	/// <returns>The expected reader.</returns>
	protected static TReader EnsureReaderType<TActual>(TActual reader)
		where TActual : IDataReader
		=> reader is TReader r ? r : throw new InvalidCastException($"Expected reader type of ({typeof(TReader)}).  Actual: ({reader.GetType()})");

	/// <inheritdoc />
	public TResult ExecuteReader<TState, TResult>(TState state, Func<IDataReader, TState, TResult> transform, CommandBehavior behavior = CommandBehavior.Default)
	{
		if (transform is null) throw new ArgumentNullException(nameof(transform));
		Contract.EndContractBlock();

		return ExecuteCore((state, transform, behavior), static (cmd, prior, s) =>
		{
			CommandBehavior b = prior == ConnectionState.Closed ? s.behavior | CommandBehavior.CloseConnection : s.behavior;
			using IDataReader reader = cmd.ExecuteReader(b);
			return s.transform(reader, s.state);
		});
	}

	/// <summary>
	/// Executes a reader on the command, passing <paramref name="state"/> to <paramref name="transform"/>.
	/// </summary>
	/// <typeparam name="TState">The type of the state passed to the transform.</typeparam>
	/// <typeparam name="TResult">The return type of the transform function.</typeparam>
	/// <param name="state">The state to pass to the transform.</param>
	/// <param name="transform">The transform function for the data reader.</param>
	/// <param name="behavior">The command behavior for once the command the reader is complete.</param>
	/// <param name="cancellationToken">
	/// A token that can cancel the call. It is used together with the command's own token; either one cancels.
	/// Through the <see cref="IExecuteReader"/> interface the token replaces the command's own.
	/// </param>
	public ValueTask<TResult> ExecuteReaderAsync<TState, TResult>(TState state, Func<IDataReader, TState, ValueTask<TResult>> transform, CommandBehavior behavior = CommandBehavior.Default, CancellationToken cancellationToken = default)
	{
		if (transform is null) throw new ArgumentNullException(nameof(transform));
		Contract.EndContractBlock();

		return CancellationTokens.RunAsync(CancellationToken, cancellationToken, (self: this, state, transform, behavior),
			static (s, token) => s.self.ExecuteReaderCoreAsync(s.state, s.transform, s.behavior, token));
	}

	// The token passed in replaces the command's own for the whole call; the caller has already combined the two.
	ValueTask<TResult> IExecuteReader.ExecuteReaderAsync<TState, TResult>(TState state, Func<IDataReader, TState, ValueTask<TResult>> transform, CommandBehavior behavior, CancellationToken cancellationToken)
	{
		if (transform is null) throw new ArgumentNullException(nameof(transform));
		Contract.EndContractBlock();

		return ExecuteReaderCoreAsync(state, transform, behavior, cancellationToken);
	}

	// The interface members that have no token: the command's own token applies, as it always did.
	ValueTask<TResult> IExecuteReader.ExecuteReaderAsync<TState, TResult>(TState state, Func<IDataReader, TState, ValueTask<TResult>> transform, CommandBehavior behavior)
		=> ExecuteReaderAsync(state, transform, behavior, default);

	ValueTask IExecuteReader<TReader>.ExecuteReaderAsync(Func<TReader, ValueTask> handler, CommandBehavior behavior)
		=> ExecuteReaderAsync(handler, behavior, default);

	ValueTask<T> IExecuteReader<TReader>.ExecuteReaderAsync<T>(Func<TReader, ValueTask<T>> handler, CommandBehavior behavior)
		=> ExecuteReaderAsync(handler, behavior, default);

	ValueTask<TResult> ExecuteReaderCoreAsync<TState, TResult>(TState state, Func<IDataReader, TState, ValueTask<TResult>> transform, CommandBehavior behavior, CancellationToken cancellationToken)
		=> ExecuteCoreAsync((state, transform, behavior, cancellationToken), static async (cmd, prior, s) =>
		{
			CommandBehavior b = prior == ConnectionState.Closed ? s.behavior | CommandBehavior.CloseConnection : s.behavior;
			if (cmd is DbCommand dbCommand)
			{
#if NETSTANDARD2_0
#else
				await
#endif
				using DbDataReader dbReader = await dbCommand.ExecuteReaderAsync(b, s.cancellationToken).ConfigureAwait(false);
				return await s.transform(dbReader, s.state).ConfigureAwait(false);
			}

			using IDataReader reader = cmd.ExecuteReader(b);
			return await s.transform(reader, s.state).ConfigureAwait(false);
		}, cancellationToken);

	/// <inheritdoc />
	public void ExecuteReader(Action<TReader> handler, CommandBehavior behavior = CommandBehavior.Default)
	{
		if (handler is null) throw new ArgumentNullException(nameof(handler));
		Contract.EndContractBlock();

		ExecuteReader(handler, static (reader, h) =>
		{
			h(EnsureReaderType(reader));
			return false;
		}, behavior);
	}

	/// <inheritdoc />
	public T ExecuteReader<T>(Func<TReader, T> transform, CommandBehavior behavior = CommandBehavior.Default)
	{
		if (transform is null) throw new ArgumentNullException(nameof(transform));
		Contract.EndContractBlock();

		return ExecuteReader(transform, static (reader, f) => f(EnsureReaderType(reader)), behavior);
	}

	/// <summary>
	/// Executes a reader on the command with a handler action.
	/// </summary>
	/// <param name="handler">The handler function for the data reader.</param>
	/// <param name="behavior">The command behavior for once the command the reader is complete.</param>
	/// <param name="cancellationToken">A token that can cancel the call. It is used together with the command's own token; either one cancels.</param>
	public ValueTask ExecuteReaderAsync(Action<TReader> handler, CommandBehavior behavior = CommandBehavior.Default, CancellationToken cancellationToken = default)
	{
		if (handler is null) throw new ArgumentNullException(nameof(handler));
		Contract.EndContractBlock();

		return ValueTaskHelpers.Discard(ExecuteReaderAsync(handler, static (reader, h) =>
		{
			h(EnsureReaderType(reader));
			return new ValueTask<bool>(false);
		}, behavior, cancellationToken));
	}

	/// <summary>
	/// Executes a reader on the command with a handler action, and a token. There is no <c>behavior</c> here: to pass both, use the overload that takes the behavior and then the token.
	/// </summary>
	/// <param name="handler">The handler function for the data reader.</param>
	/// <param name="cancellationToken">A token that can cancel the call. It is used together with the command's own token; either one cancels.</param>
	public ValueTask ExecuteReaderAsync(Action<TReader> handler, CancellationToken cancellationToken)
		=> ExecuteReaderAsync(handler, CommandBehavior.Default, cancellationToken);

	/// <summary>
	/// Executes a reader on the command with a transform function.
	/// </summary>
	/// <typeparam name="T">The type of the result.</typeparam>
	/// <param name="handler">The handler function for the data reader.</param>
	/// <param name="behavior">The command behavior for once the command the reader is complete.</param>
	/// <param name="cancellationToken">A token that can cancel the call. It is used together with the command's own token; either one cancels.</param>
	public ValueTask<T> ExecuteReaderAsync<T>(Func<TReader, T> handler, CommandBehavior behavior = CommandBehavior.Default, CancellationToken cancellationToken = default)
	{
		if (handler is null) throw new ArgumentNullException(nameof(handler));
		Contract.EndContractBlock();

		return ExecuteReaderAsync(handler, static (reader, h) => new ValueTask<T>(h(EnsureReaderType(reader))), behavior, cancellationToken);
	}

	/// <summary>
	/// Executes a reader on the command with a transform function, and a token. There is no <c>behavior</c> here: to pass both, use the overload that takes the behavior and then the token.
	/// </summary>
	/// <typeparam name="T">The type of the result.</typeparam>
	/// <param name="handler">The handler function for the data reader.</param>
	/// <param name="cancellationToken">A token that can cancel the call. It is used together with the command's own token; either one cancels.</param>
	public ValueTask<T> ExecuteReaderAsync<T>(Func<TReader, T> handler, CancellationToken cancellationToken)
		=> ExecuteReaderAsync(handler, CommandBehavior.Default, cancellationToken);

	/// <summary>
	/// Executes a reader on the command with an asynchronous handler function.
	/// </summary>
	/// <param name="handler">The handler function for the data reader.</param>
	/// <param name="behavior">The command behavior for once the command the reader is complete.</param>
	/// <param name="cancellationToken">A token that can cancel the call. It is used together with the command's own token; either one cancels.</param>
	public ValueTask ExecuteReaderAsync(Func<TReader, ValueTask> handler, CommandBehavior behavior = CommandBehavior.Default, CancellationToken cancellationToken = default)
	{
		if (handler is null) throw new ArgumentNullException(nameof(handler));
		Contract.EndContractBlock();

		return ValueTaskHelpers.Discard(ExecuteReaderAsync(handler, static async (reader, h) =>
		{
			await h(EnsureReaderType(reader)).ConfigureAwait(false);
			return false;
		}, behavior, cancellationToken));
	}

	/// <summary>
	/// Executes a reader on the command with an asynchronous handler function, and a token. There is no <c>behavior</c> here: to pass both, use the overload that takes the behavior and then the token.
	/// </summary>
	/// <param name="handler">The handler function for the data reader.</param>
	/// <param name="cancellationToken">A token that can cancel the call. It is used together with the command's own token; either one cancels.</param>
