	void IExecuteReader.ExecuteReader(Action<IDataReader> handler, CommandBehavior behavior)
	{
		if (handler is null) throw new ArgumentNullException(nameof(handler));
		Contract.EndContractBlock();

		ExecuteReader(handler, static (reader, h) =>
		{
			h(reader);
			return false;
		}, behavior);
	}

	T IExecuteReader.ExecuteReader<T>(Func<IDataReader, T> transform, CommandBehavior behavior)
	{
		if (transform is null) throw new ArgumentNullException(nameof(transform));
		Contract.EndContractBlock();

		return ExecuteReader(transform, static (reader, f) => f(reader), behavior);
	}

	ValueTask IExecuteReader.ExecuteReaderAsync(Func<IDataReader, ValueTask> handler, CommandBehavior behavior)
	{
		if (handler is null) throw new ArgumentNullException(nameof(handler));
		Contract.EndContractBlock();

		return ValueTaskHelpers.Discard(ExecuteReaderAsync(handler, static async (reader, h) =>
		{
			await h(reader).ConfigureAwait(false);
			return false;
		}, behavior));
	}

	ValueTask<T> IExecuteReader.ExecuteReaderAsync<T>(Func<IDataReader, ValueTask<T>> transform, CommandBehavior behavior)
	{
		if (transform is null) throw new ArgumentNullException(nameof(transform));
		Contract.EndContractBlock();

		return ExecuteReaderAsync(transform, static (reader, f) => f(reader), behavior);
	}

	/// <summary>
	/// Calls ExecuteNonQuery on the underlying command but sets up a return parameter and returns that value.
	/// </summary>
	/// <returns>The value from the return parameter.</returns>
	public object? ExecuteReturn()
		// Open MUST occur before command creation as some DbCommands require it.
		=> ExecuteCore(0, static (cmd, _, _) =>
		{
			IDbDataParameter returnParameter = cmd.AddReturnParameter();
			cmd.ExecuteNonQuery();
			return returnParameter.Value;
		});

	/// <summary>
	/// Calls ExecuteNonQuery on the underlying command but sets up a return parameter and returns that value.
	/// </summary>
	/// <typeparam name="T">The type expected.</typeparam>
	/// <returns>The value from the return parameter; <see langword="default"/> when it is NULL.</returns>
	/// <exception cref="InvalidCastException">The value is not of type <typeparamref name="T"/>.</exception>
	public T ExecuteReturn<T>()
		=> CastScalar<T>(ExecuteReturn());

	/// <summary>
	/// Calls ExecuteNonQueryAsync on the underlying command but sets up a return parameter and returns that value.
	/// </summary>
	/// <inheritdoc cref="ExecuteReturn()"/>
	/// <param name="cancellationToken">A token that can cancel the call. It is used together with the command's own token; either one cancels.</param>
	public ValueTask<object?> ExecuteReturnAsync(CancellationToken cancellationToken = default)
	{
		// Thrown synchronously, as before: both tokens are checked before anything is linked.
		CancellationToken.ThrowIfCancellationRequested();
		cancellationToken.ThrowIfCancellationRequested();

		return ExecuteCombinedAsync(cancellationToken, static async (cmd, _, token) =>
		{
			IDbDataParameter returnParameter = cmd.AddReturnParameter();

			if (cmd is DbCommand dbCommand)
				await dbCommand.ExecuteNonQueryAsync(token).ConfigureAwait(false);
			else
				cmd.ExecuteNonQuery();

			return returnParameter.Value;
		})!;
	}

	/// <summary>
	/// Calls ExecuteNonQueryAsync on the underlying command but sets up a return parameter and returns that value.
	/// </summary>
	/// <inheritdoc cref="ExecuteReturn{T}()"/>
	/// <param name="cancellationToken">A token that can cancel the call. It is used together with the command's own token; either one cancels.</param>
	public async ValueTask<T> ExecuteReturnAsync<T>(CancellationToken cancellationToken = default)
		=> CastScalar<T>(await ExecuteReturnAsync(cancellationToken).ConfigureAwait(false));

	/// <summary>
	/// Calls ExecuteNonQuery on the underlying command.
	/// </summary>
	/// <returns>The integer response from the method. (Records updated.)</returns>
	public int ExecuteNonQuery()
		=> Execute(command => command.ExecuteNonQuery());

	/// <summary>
	/// Calls ExecuteScalar on the underlying command.
	/// </summary>
	/// <returns>The raw value the provider returns: <see cref="DBNull.Value"/> when the column is NULL and <see langword="null"/> when there is no row, which is how to tell the two apart. Use <see cref="ExecuteScalar{T}()"/> for <c>default</c> in both cases, or a transform overload to receive <see langword="null"/> in both.</returns>
	public object? ExecuteScalar()
		=> Execute(command => command.ExecuteScalar());

	/// <summary>
	/// Calls ExecuteScalar on the underlying command and casts to the expected type.
	/// </summary>
	/// <typeparam name="T">The type expected.</typeparam>
	/// <returns>The value returned from the method; <see langword="default"/> when the result is NULL or there was no row.</returns>
	/// <exception cref="InvalidCastException">The value is not of type <typeparamref name="T"/>.</exception>
	public T ExecuteScalar<T>()
		=> CastScalar<T>(ExecuteScalar());

	// NULL and no row (null or DBNull) become default(T) for every T; anything else is the plain cast.
	private protected static T CastScalar<T>(object? value)
		=> value is null or DBNull ? default! : (T)value;

	// What the transform overloads hand to the user's function: NULL (DBNull) becomes null, like no row; any other value is passed unchanged.
	private protected static object? ScalarValue(object? value)
		=> value is DBNull ? null : value;

	/// <summary>
	/// Calls ExecuteScalar on the underlying command.
	/// </summary>
	/// <typeparam name="T">The type expected.</typeparam>
	/// <param name="transform">The function that converts the value. It receives <see langword="null"/> when the column is NULL or there is no row, never <see cref="DBNull"/>; any other value is passed as the provider returned it.</param>
	/// <returns>The value returned from the transform.</returns>
	public T ExecuteScalar<T>(Func<object?, T> transform)
	{
		if (transform is null) throw new ArgumentNullException(nameof(transform));
		Contract.EndContractBlock();

		return transform(ScalarValue(ExecuteScalar()));
	}
}
